    const stroke = n.style?.stroke ?? "#000";
    const lw = n.style?.lineWidth ?? 1.5;
    const dash = Array.isArray(n.style?.lineDash) && n.style?.lineDash.length ? ` stroke-dasharray="4 4"` : "";
